"""Valid Palindrome II — two pointers with one allowed deletion.

Walk inwards; on the first mismatch the answer is a palindrome only if skipping
the left or the right character fixes the rest.

Time: O(n)   Space: O(1)
"""


class Solution:
    def validPalindrome(self, s: str) -> bool:
        def is_palindrome(lo: int, hi: int) -> bool:
            while lo < hi:
                if s[lo] != s[hi]:
                    return False
                lo += 1
                hi -= 1
            return True

        lo, hi = 0, len(s) - 1
        while lo < hi:
            if s[lo] != s[hi]:
                return is_palindrome(lo + 1, hi) or is_palindrome(lo, hi - 1)
            lo += 1
            hi -= 1
        return True
